gNT(){return"\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0423\u043d\u0446\u0438\u0430\u043b 0169 \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0435 \u041f\u0440\u0438\u043d\u0441\u0442\u043e\u043d\u0441\u043a\u043e\u0439 \u0442\u0435\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u0435\u043c\u0438\u043d\u0430\u0440\u0438\u0438 \u0432 \u041f\u0440\u0438\u043d\u0441\u0442\u043e\u043d\u0435, \u0421\u0428\u0410."},
